-- Seed the real Batch 11 active voter list from active-voter-list.csv.
-- Roll is retained as student_id; phone and email come from the source CSV.
-- All imported rows are regular active members. Role and status are not
-- present in the CSV, so no admin privileges or non-active states are inferred.
-- The CSV uses BAD for Business Administration (BA) and BANGLA for Bangla (BAN).
-- Depends on seed_disciplines.sql having run first.


-- Roll numbers are admin-only, so they must not double as public URLs.
-- Rewrites the slugs inserted above (see db/migrations/007).
update members
set slug = coalesce(
      nullif(trim(both '-' from left(regexp_replace(lower(name), '[^a-z0-9]+', '-', 'g'), 40)), ''),
      'member'
    ) || '-' || substr(md5(random()::text || id::text), 1, 6)
where student_id is not null and slug = student_id;
